import { componentName, type ExportTarget } from './types'

export const vueLibTarget: ExportTarget = {
  id: 'vue-lib',
  label: 'Vue (renderer package)',
  description: 'A small SFC using @formsgen/renderer — schema-driven, always in sync.',
  frameworkAware: false,
  generate: ({ schema }) => {
    const name = componentName(schema)
    const schemaLiteral = JSON.stringify(schema, null, 2).replace(/\n/g, '\n')
    return [
      {
        path: `${name}.vue`,
        language: 'xml',
        content: `<script setup lang="ts">
// Generated by FormsGen. Renders via @formsgen/renderer.
import { ref } from 'vue'
import { FormsGenForm, type FormSchema } from '@formsgen/renderer'
import '@formsgen/renderer/style.css'

const schema = ${schemaLiteral} as unknown as FormSchema

const data = ref<Record<string, unknown>>({})

function onSubmit(payload: Record<string, unknown>): void {
  // Replace with your submit handling.
  console.log('${name} submitted', payload)
}
</script>

<template>
  <FormsGenForm
    v-model="data"
    :schema="schema"
    @submit="onSubmit"
  />
</template>
`,
      },
    ]
  },
  readme: ({ schema }) => `# ${componentName(schema)} (Vue 3, @formsgen/renderer)

## Install

1. Build the renderer package from the FormsGen monorepo:
   \`pnpm --filter @formsgen/renderer build && pnpm --filter @formsgen/renderer pack\`
2. Install the tarball in your project (or publish it to your registry):
   \`npm i ./formsgen-renderer-*.tgz\`
3. Drop \`${componentName(schema)}.vue\` anywhere in your app and use it:

\`\`\`html
<${componentName(schema)} />
\`\`\`

Styling is the renderer's self-contained vanilla theme (dark-mode and RTL
aware, themeable via \`meta.theme\` tokens in the schema). Validation and
conditional visibility run inside the renderer — edit the schema, not the
component, to change behavior.
`,
}
